      const col = view(Float64Array, ex.zpb_col_ptr(), n);
      for (let i = 0; i < n; i++) sum += col[i];
      ex.zpb_col_free();
      return { rows: n, sum };
    } finally {
      ex.zpb_free(p, bytes.length);
    }
  },
};
