1	// Runtime-agnostic runner. Timing uses the injected `now()` (ms).
2	import { SCENARIOS, generate, expectedSum } from "./gen.js";
3	import { zig } from "./libs/zig.js";
4	import { hyparquet } from "./libs/hyparquet.js";
5	import { parquetWasm } from "./libs/parquet-wasm.js";
6	
7	export const RUNS = 3;
8	export const INTEROP_ROWS = 1000;
9	const ADAPTERS = [zig, hyparquet, parquetWasm];
10	
11	/** Initialise every adapter. Failures are kept (as `error`) and reported as n/a. */
12	export async function initLibs(assets, log = () => {}) {
13	  const out = [];
14	  for (const adapter of ADAPTERS) {
15	    try {
16	      await adapter.init(assets);
17	      out.push({ adapter, error: null });
18	    } catch (e) {
19	      log(`[init] ${adapter.name}: ${e?.message ?? e}`);
20	      out.push({ adapter, error: String(e?.message ?? e) });
21	    }
22	  }
23	  return out;
24	}
25	
26	function checkResult(res, rows, want) {
27	  if (res.rows !== rows || res.sum !== want) {
28	    throw new Error(`checksum mismatch: got rows=${res.rows} sum=${res.sum}, want rows=${rows} sum=${want}`);
29	  }
30	}
31	
32	/** Write every scenario with every library, then read each output with every library. */
33	export async function interop(libs, log = () => {}) {
34	  const ok = libs.filter((l) => !l.error);
35	  const pairs = [];
36	  for (const w of ok) for (const r of ok) pairs.push({ writer: w.adapter.name, reader: r.adapter.name, cells: {} });
37	  for (const scn of SCENARIOS) {
38	    const data = generate(scn, INTEROP_ROWS);
39	    const want = expectedSum(scn, data);
40	    for (const w of ok) {
41	      let bytes = null;
42	      let writeErr = null;
43	      try {
44	        bytes = await w.adapter.write(scn, data);
45	      } catch (e) {
46	        writeErr = `write: ${e.message}`;
47	      }
48	      for (const r of ok) {
49	        const pair = pairs.find((p) => p.writer === w.adapter.name && p.reader === r.adapter.name);
50	        if (writeErr) { pair.cells[scn.name] = "ERR"; log(`[interop] ${w.adapter.name} ${scn.name} ${writeErr}`); continue; }
51	        try {
52	          checkResult(await r.adapter.read(bytes, scn), INTEROP_ROWS, want);
53	          pair.cells[scn.name] = "ok";
54	        } catch (e) {
55	          pair.cells[scn.name] = "ERR";
56	          log(`[interop] ${w.adapter.name} -> ${r.adapter.name} ${scn.name}: ${e.message}`);
57	        }
58	      }
59	    }
60	  }
61	  // Libraries that failed to init show as n/a in the matrix.
62	  for (const l of libs.filter((l) => l.error)) {
63	    pairs.push({ writer: l.adapter.name, reader: "*", cells: Object.fromEntries(SCENARIOS.map((s) => [s.name, "n/a"])) });
64	  }
65	  return { scenarios: SCENARIOS.map((s) => s.name), pairs };
66	}
67	
68	/** Timed benchmark. Each phase runs `runs` times; the best time is kept. */
69	export async function runBench({ rows, libs, log = () => {}, now = () => performance.now(), runs = RUNS, skipInterop = false }) {
70	  const t0 = now();
71	  const interopResult = skipInterop ? null : await interop(libs, log);
72	  const results = [];
73	  for (const scn of SCENARIOS) {
74	    const data = generate(scn, rows);
75	    const want = expectedSum(scn, data);
76	    for (const { adapter, error } of libs) {
77	      const rec = {
78	        lib: adapter.name, scenario: scn.name, rows,
79	        write_ms: null, write_rows_per_s: null, read_ms: null, read_rows_per_s: null, file_MB: null,
80	        status: "ok", error: null,
81	      };
82	      if (error) {
83	        rec.status = "n/a";
84	        rec.error = error;
85	        results.push(rec);
86	        continue;
87	      }
88	      let bestW = Infinity;
89	      let bestR = Infinity;
90	      try {
91	        for (let run = 0; run < runs; run++) {
92	          let s = now();
93	          const bytes = await adapter.write(scn, data);
94	          bestW = Math.min(bestW, now() - s);
95	          rec.file_MB = bytes.byteLength / (1024 * 1024);
96	          s = now();
97	          const res = await adapter.read(bytes, scn);
98	          bestR = Math.min(bestR, now() - s);
99	          checkResult(res, rows, want);
100	          log(`[${adapter.name}] ${scn.name} run ${run + 1}: write ${(bestW).toFixed(1)}ms read ${bestR.toFixed(1)}ms`);
101	        }
102	        rec.write_ms = bestW;
103	        rec.read_ms = bestR;
104	        rec.write_rows_per_s = rows / (bestW / 1000);
105	        rec.read_rows_per_s = rows / (bestR / 1000);
106	      } catch (e) {
107	        rec.status = "ERR";
108	        rec.error = e?.message ?? String(e);
109	        log(`[${adapter.name}] ${scn.name} ERR: ${rec.error}`);
110	      }
111	      results.push(rec);
112	    }
113	  }
114	  const table = formatTable(rows, results);
115	  return { rows, results, interop: interopResult, elapsed_ms: now() - t0, table };
116	}
117	
118	const fmt = (v, digits) => (v == null ? "n/a" : v.toFixed(digits));
119	
120	/** Fixed-width table in the native bench's column style. */
121	export function formatTable(rows, results) {
122	  const head = [
123	    "lib".padEnd(18), "scenario".padEnd(15), "rows".padStart(9), "write_ms".padStart(10),
124	    "write_rows_per_s".padStart(17), "read_ms".padStart(10), "read_rows_per_s".padStart(16), "file_MB".padStart(9),
125	  ].join(" ");
126	  const lines = [head];
127	  const notes = [];
128	  // Cell text: n/a for unsupported, ERR for failures, otherwise the number.
129	  const cell = (r, v, digits, width) => {
130	    let t;
131	    if (r.status === "n/a") t = "n/a";
132	    else if (v == null) t = "ERR";
133	    else t = Number.isFinite(v) ? v.toFixed(digits) : "n/a";
134	    return t.padStart(width);
135	  };
136	  for (const r of results) {
137	    lines.push([
138	      r.lib.padEnd(18), r.scenario.padEnd(15), String(rows).padStart(9),
139	      cell(r, r.write_ms, 2, 10),
140	      cell(r, r.write_rows_per_s, 0, 17),
141	      cell(r, r.read_ms, 2, 10),
142	      cell(r, r.read_rows_per_s, 0, 16),
143	      cell(r, r.file_MB, 2, 9),
144	    ].join(" "));
145	    if (r.error) notes.push(`  ${r.lib} ${r.scenario}: ${r.error}`);
146	  }
147	  const body = lines.join("\n");
148	  return notes.length ? body + "\nnotes:\n" + notes.join("\n") : body;
149	}
150	
151	/** Interop matrix as text. */
152	export function formatInterop(io) {
153	  if (!io) return "(interop skipped)";
154	  const w = (s, n) => s.padEnd(n);
155	  const lines = [`interop (${INTEROP_ROWS} rows) writer -> reader`];
156	  lines.push(w("writer -> reader", 52) + io.scenarios.map((s) => s.padEnd(15)).join(""));
157	  for (const p of io.pairs) {
158	    lines.push(w(`${p.writer} -> ${p.reader}`, 52) + io.scenarios.map((s) => (p.cells[s] ?? "-").padEnd(15)).join(""));
159	  }
160	  return lines.join("\n");
161	}
